// 05 Section 9's own numbers, verbatim: 7-day, then 30/60/90-day, then quarterly (90 days) after.
const INTERVALS_DAYS = [7, 30, 60, 90];
const QUARTERLY_DAYS = 90;
const MS_PER_DAY = 86400000;

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.companies)) return json.data.companies;
  if (json && Array.isArray(json.companies)) return json.companies;
  return [];
}

const now = new Date();
const due = [];

for (const company of $input.all().flatMap(asArray)) {
  const wave = company.cxWave || 0;
  const anchor = company.lastCxTouchAt || company.liveClientSince;
  if (!anchor) continue; // no liveClientSince yet is unexpected (W1.6 always sets it) - skip rather than guess a start date.
  const intervalDays = wave < INTERVALS_DAYS.length ? INTERVALS_DAYS[wave] : QUARTERLY_DAYS;
  const daysSince = (now - new Date(anchor)) / MS_PER_DAY;
  if (daysSince >= intervalDays) {
    due.push({ ...company, nextWave: wave + 1 });
  }
}

return due.map((c) => ({ json: c }));

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { draftText: textBlock.text } }];
